// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICoinToken {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Create an instance of the target contract
                ICoinToken victim = ICoinToken(TARGET);

                // Get the owner of the contract
                address owner = victim.owner();

                // Impersonate the owner
                vm.startPrank(owner);

                // Call the pause function
                victim.pause();

                // Stop impersonating
                vm.stopPrank();
        assertEq(victim.paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
